import { setupSearch, normalizeString } from './common_search.js'; document.addEventListener('DOMContentLoaded', () => { setupSearch({ tabId: 'site-search', dataPath: './search_data.json', filterLogic: (query, searchData) => { const keywords = normalizeString(query).split(/\s+/).filter(k => k.length > 0); if (keywords.length === 0) return []; const filtered = searchData.filter(item => { const title = normalizeString(item.title); const kws = normalizeString(item.keywords); const desc = normalizeString(item.description); return keywords.every(word =>
title.includes(word) || kws.includes(word) || desc.includes(word)
); }); return filtered.sort((a, b) => { const aTitleMatch = keywords.some(word => normalizeString(a.title).includes(word)); const bTitleMatch = keywords.some(word => normalizeString(b.title).includes(word)); return (aTitleMatch && !bTitleMatch) ? -1 : (!aTitleMatch && bTitleMatch) ? 1 : 0; }); }, onDataLoaded: () => { } }); });